    (v_route, 'Rozhledna na Velké Sově', 'Rozhledna v Polsku — výhled do kraje jako odměna za zastávku.', 50.68025, 16.48562, 'http://commons.wikimedia.org/wiki/Special:FilePath/2016%20Wie%C5%BCa%20widokowa%20na%20Wielkiej%20Sowie%202.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2016%20Wie%C5%BCa%20widokowa%20na%20Wielkiej%20Sowie%202.jpg"}'::text[], 0, '{"en": {"name": "Bismarck tower on Wielka Sowa", "description": "A lookout tower in Poland — sweeping views as a reward for stopping."}, "de": {"name": "Aussichtsturm auf der Hohen Eule", "description": "Ein Aussichtsturm in Polen — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża widokowa na Wielkiej Sowie", "description": "Wieża widokowa. Wieża widokowa w Polsce — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Rozhledna na Velké Sově", "description": "Een uitkijktoren in Polen — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Rozhledna na Velké Sově", "description": "Un mirador en Polonia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Rozhledna na Velké Sově", "description": "Une tour panoramique en Pologne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Rozhledna na Velké Sově", "description": "Оглядова вежа в Польщі — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Rozhledna na hoře svaté Anny', 'Rozhledna v Polsku — výhled do kraje jako odměna za zastávku.', 50.56672, 16.5019, 'http://commons.wikimedia.org/wiki/Special:FilePath/2025%20Wie%C5%BCa%20widokowa%20na%20G%C3%B3rze%20%C5%9Awi%C4%99tej%20Anny%20%282%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2025%20Wie%C5%BCa%20widokowa%20na%20G%C3%B3rze%20%C5%9Awi%C4%99tej%20Anny%20%282%29.jpg"}'::text[], 1, '{"en": {"name": "Former observation tower on St. Anna’s Mountain in Nowa Ruda", "description": "Tower in Nowa Ruda, Lower Silesian Voivodeship, Poland. A lookout tower in Poland — sweeping views as a reward for stopping."}, "de": {"name": "Rozhledna na hoře svaté Anny", "description": "Turm in Polen. Ein Aussichtsturm in Polen — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża widokowa na Górze Świętej Anny", "description": "Zabytek nieruchomy w województwie dolnośląskim. Wieża widokowa w Polsce — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Rozhledna na hoře svaté Anny", "description": "Pools monument in Nowa Ruda. Een uitkijktoren in Polen — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Rozhledna na hoře svaté Anny", "description": "Un mirador en Polonia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Rozhledna na hoře svaté Anny", "description": "Une tour panoramique en Pologne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Rozhledna na hoře svaté Anny", "description": "Оглядова вежа в Польщі — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Rozhledna na Hoře Všech svatých', 'Rozhledna v Polsku — výhled do kraje jako odměna za zastávku.', 50.55074, 16.52117, 'http://commons.wikimedia.org/wiki/Special:FilePath/2015%20Wie%C5%BCa%20widokowa%20na%20G%C3%B3rze%20Wszystkich%20%C5%9Awi%C4%99tych.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2015%20Wie%C5%BCa%20widokowa%20na%20G%C3%B3rze%20Wszystkich%20%C5%9Awi%C4%99tych.jpg"}'::text[], 2, '{"en": {"name": "Rozhledna na Hoře Všech svatých", "description": "A lookout tower in Poland — sweeping views as a reward for stopping."}, "de": {"name": "Moltketurm (Nowa Ruda)", "description": "Turm in Słupiec (Nowa Ruda), Woiwodschaft Niederschlesien, Polen. Ein Aussichtsturm in Polen — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża widokowa na Górze Wszystkich Świętych", "description": "Wieża widokowa. Wieża widokowa w Polsce — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Rozhledna na Hoře Všech svatých", "description": "Een uitkijktoren in Polen — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Rozhledna na Hoře Všech svatých", "description": "Un mirador en Polonia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Rozhledna na Hoře Všech svatých", "description": "Une tour panoramique en Pologne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Rozhledna na Hoře Všech svatých", "description": "Оглядова вежа в Польщі — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Zaniklá rozhledna na Králickém Sněžníku', 'Zaniklá kamenná rozhledna postavená v letech 1895–1899. Nacházela se na polské straně asi 40 m od vrcholu stejnojmenné hory ve stejnojmenném pohoří. V dolní části rozhledny byl hostinec. V roce 1973 z bezpečnostních důvodů zbořena. Rozhledna v Polsku — výhled do kraje jako odměna za zastávku.', 50.2076, 16.8471, 'http://commons.wikimedia.org/wiki/Special:FilePath/Die%20Gartenlaube%20%281899%29%20b%200389.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Die%20Gartenlaube%20%281899%29%20b%200389.jpg"}'::text[], 3, '{"en": {"name": "Former observation tower on Śnieżnik", "description": "A lookout tower in Poland — sweeping views as a reward for stopping."}, "de": {"name": "Kaiser-Wilhelm-Turm", "description": "Ruine in Polen. Ein Aussichtsturm in Polen — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Dawna wieża widokowa na Śnieżniku (1899)", "description": "Powstała w 1899 roku, obecnie rozebrana, wieża na górze Śnieżnik. Wieża widokowa w Polsce — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Zaniklá rozhledna na Králickém Sněžníku", "description": "Uitkijktoren in Polen. Een uitkijktoren in Polen — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Zaniklá rozhledna na Králickém Sněžníku", "description": "Un mirador en Polonia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Zaniklá rozhledna na Králickém Sněžníku", "description": "Une tour panoramique en Pologne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Zaniklá rozhledna na Králickém Sněžníku", "description": "Оглядова вежа в Польщі — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Rozhledna na Králickém Sněžníku', 'Postavena v roce 2022 asi 12 m jihozápadně od místa bývalé kamenné rozhledny. Nachází se na polské straně asi 45 m od vrcholu stejnojmenné hory ve stejnojmenném pohoří. Rozhledna v Polsku — výhled do kraje jako odměna za zastávku.', 50.20755, 16.84706, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wie%C5%BCa%20widokowa%20na%20%C5%9Anie%C5%BCniku%20%282022%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Wie%C5%BCa%20widokowa%20na%20%C5%9Anie%C5%BCniku%20%282022%29.jpg"}'::text[], 4, '{"en": {"name": "observation tower on Śnieżnik", "description": "A lookout tower in Poland — sweeping views as a reward for stopping."}, "de": {"name": "Aussichtsturm auf dem Glatzer Schneeberg", "description": "Ein Aussichtsturm in Polen — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża widokowa na Śnieżniku (2022)", "description": "Wieża widokowa w Polsce — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Rozhledna na Králickém Sněžníku", "description": "Een uitkijktoren in Polen — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Rozhledna na Králickém Sněžníku", "description": "Un mirador en Polonia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Rozhledna na Králickém Sněžníku", "description": "Une tour panoramique en Pologne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Rozhledna na Králickém Sněžníku", "description": "Оглядова вежа в Польщі — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Vodárenská věž', 'Vodárenská věž ve Vratislavi Borek. Rozhledna v Polsku — výhled do kraje jako odměna za zastávku.', 51.08523, 17.01756, 'http://commons.wikimedia.org/wiki/Special:FilePath/Breslau%20Wroclaw%20Wasserturm.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Breslau%20Wroclaw%20Wasserturm.jpg"}'::text[], 5, '{"en": {"name": "Wrocław water tower", "description": "Water tower in Poland. A lookout tower in Poland — sweeping views as a reward for stopping."}, "de": {"name": "Wasserturm Breslau", "description": "Ein Aussichtsturm in Polen — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża ciśnień przy alei Wiśniowej we Wrocławiu", "description": "Zabytek nieruchomy w województwie dolnośląskim. Wieża widokowa w Polsce — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Wrocław water tower", "description": "Een uitkijktoren in Polen — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Vodárenská věž", "description": "Un mirador en Polonia: amplias vistas como recompensa por la parada."}, "fr": {"name": "château d''eau de l''allée Wiśniowa de Wrocław", "description": "Une tour panoramique en Pologne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Вроцлавська водонапірна вежа", "description": "Оглядова вежа в Польщі — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
