    (v_route, 'Stezka v oblacích', 'Vyhlídková konstrukce nad obcí Dolní Morava poblíž chaty Slaměnka pod vrcholem Slamníku v masivu Králický Sněžník. Rozhledna v Česku — výhled do kraje jako odměna za zastávku.', 50.14943, 16.82919, 'http://commons.wikimedia.org/wiki/Special:FilePath/Stezka%20v%20oblacich.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Stezka%20v%20oblacich.jpg"}'::text[], 0, '{"en": {"name": "Sky Walk", "description": "Observation tower in Czechia. A lookout tower in Czechia — sweeping views as a reward for stopping."}, "de": {"name": "Pfad in den Wolken", "description": "Aussichtsturm in Tschien. Ein Aussichtsturm in Tschechien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Stezka v oblacích", "description": "Wieża widokowa w Czechach — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Stezka v oblacích", "description": "Een uitkijktoren in Tsjechië — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Stezka v oblacích", "description": "Un mirador en Chequia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Stezka v oblacích", "description": "Une tour panoramique en Tchéquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Stezka v oblacích", "description": "Оглядова вежа в Чехії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
