    (v_route, 'Hraniční vrch', 'Rozhledna v Česku. Rozhledna v Česku — výhled do kraje jako odměna za zastávku.', 50.17167, 17.60417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Hrani%C4%8Dn%C3%AD%20vrch%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Hrani%C4%8Dn%C3%AD%20vrch%2001.jpg"}'::text[], 2, '{"en": {"name": "Rozhledna Hraniční vrch", "description": "A lookout tower in Czechia — sweeping views as a reward for stopping."}, "de": {"name": "Aussichtsturm Hraniční vrch", "description": "Aussichtsturm in Tschechien. Ein Aussichtsturm in Tschechien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Graniczna Góra", "description": "Wieża widokowa w Czechach — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Hraniční vrch", "description": "Een uitkijktoren in Tsjechië — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Hraniční vrch", "description": "Un mirador en Chequia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Hraniční vrch", "description": "Une tour panoramique en Tchéquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Hraniční vrch", "description": "Оглядова вежа в Чехії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Pastýřka', 'Rozhledna u Moravské Třebové. Rozhledna v Česku — výhled do kraje jako odměna za zastávku.', 49.7481, 16.6628, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Past%C3%BD%C5%99ka.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Past%C3%BD%C5%99ka.JPG"}'::text[], 3, '{"en": {"name": "Pastýřka", "description": "Observation tower. A lookout tower in Czechia — sweeping views as a reward for stopping."}, "de": {"name": "Pastýřka", "description": "Ein Aussichtsturm in Tschechien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Pastýřka", "description": "Wieża widokowa w Czechach — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Pastýřka", "description": "Uitkijktoren in Tsjechië. Een uitkijktoren in Tsjechië — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Pastýřka", "description": "Un mirador en Chequia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Pastýřka", "description": "Une tour panoramique en Tchéquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Pastýřka", "description": "Оглядова вежа в Чехії — широкі краєвиди як нагорода за зупинку."}}'::jsonb);
