  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Big Ben', 'Zvon v hodinové věži na severním konci Westminsterského paláce. Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.50067, -0.12449, 'http://commons.wikimedia.org/wiki/Special:FilePath/Big%20Ben%202001-06-27.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Big%20Ben%202001-06-27.jpg"}'::text[], 0, '{"en": {"name": "Big Ben", "description": "Tower of the Palace of Westminster, London containing the bell Big Ben. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "Big Ben", "description": "Uhrturm am Palace of Westminster in London mit der Glocke Big Ben. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Big Ben", "description": "Wieża zegarowa w Londynie. Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Big Ben", "description": "Klok in City of Westminster, Verenigd Koninkrijk/Engeland. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Big Ben", "description": "Torre del Palacio de Westminster en Londres, Inglaterra. Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "Big Ben", "description": "Tour horloge du Palais de Westminster à Londres. Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Біг-Бен", "description": "Популярна туристична назва годинникової вежі Вестмінстерського палацу. Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Věž British Telecom', 'Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.5215, -0.1389, 'http://commons.wikimedia.org/wiki/Special:FilePath/BT%20Tower-1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/BT%20Tower-1.jpg"}'::text[], 1, '{"en": {"name": "BT Tower", "description": "Communications tower located in Fitzrovia, London, England, UK. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "BT Tower", "description": "Londoner Fernsehturm. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "BT Tower", "description": "Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "BT Tower", "description": "Communicatietoren in Camden, Verenigd Koninkrijk. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre BT", "description": "Torre de telecomunicaciones en Reino Unido. Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "BT Tower", "description": "Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Věž British Telecom", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'ArcelorMittal Orbit', 'Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.53833, -0.01333, 'http://commons.wikimedia.org/wiki/Special:FilePath/ArcelorMittal%20Orbit%20at%20night.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/ArcelorMittal%20Orbit%20at%20night.jpg"}'::text[], 2, '{"en": {"name": "ArcelorMittal Orbit", "description": "Sculpture and observation tower in the Olympic Park in Stratford, London. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "ArcelorMittal Orbit", "description": "Skulptur von Anish Kapoor und Cecil Balmond im Olympic Park in Stratford, London. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "ArcelorMittal Orbit", "description": "Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "ArcelorMittal Orbit", "description": "Bouwwerk in Londen. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "ArcelorMittal Orbit", "description": "Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour Orbit", "description": "Œuvre de Anish Kapoor et Cecil Balmond. Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "ArcelorMittal Orbit", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Watkin''s Tower', 'Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.55556, -0.27944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Watkin%20tower%20first%20stage.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Watkin%20tower%20first%20stage.jpg"}'::text[], 3, '{"en": {"name": "Watkin''s Tower", "description": "Partially completed iron lattice tower in London, England. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "Watkins Tower", "description": "Unvollendetes Turmbauvorhaben in London. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Watkin’s Tower", "description": "Konstrukcja kratowa z kutego żelaza (nieukończona wieża; Londyn, Wielka Brytania; 1894–1907). Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Watkin''s Tower", "description": "Folly in Londen, Verenigd Koninkrijk. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre de Watkin", "description": "Torre de celosía de hierro parcialmente terminada en Londres, Inglaterra. Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour de Watkin", "description": "Tour inachevée de Londres. Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Watkin''s Tower", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb);
