  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Berliner Fernsehturm', 'Televizní věž v Berlíně. Rozhledna v Německu — výhled do kraje jako odměna za zastávku.', 52.52083, 13.40944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tv-turm%20-%20panoramio.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tv-turm%20-%20panoramio.jpg"}'::text[], 0, '{"en": {"name": "Fernsehturm Berlin", "description": "Television tower in Berlin. A lookout tower in Germany — sweeping views as a reward for stopping."}, "de": {"name": "Berliner Fernsehturm", "description": "Sende- und Aussichtsturm in Berlin. Ein Aussichtsturm in Deutschland — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Fernsehturm w Berlinie", "description": "Wieża telewizyjna. Wieża widokowa w Niemczech — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Fernsehturm", "description": "Bouwwerk in Berlijn. Een uitkijktoren in Duitsland — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre de televisión de Berlin", "description": "Torre de transmisión y observación en Berlín, Alemania. Un mirador en Alemania: amplias vistas como recompensa por la parada."}, "fr": {"name": "Fernsehturm de Berlin", "description": "Tour à Berlin. Une tour panoramique en Allemagne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Берлінська телевежа", "description": "Телевежа, що є найвищою спорудою Німеччини. Оглядова вежа в Німеччині — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Funkturm Berlin', 'Bývalý vysílač v Berlíně, dnes rozhledna. Rozhledna v Německu — výhled do kraje jako odměna za zastávku.', 52.50506, 13.27818, 'http://commons.wikimedia.org/wiki/Special:FilePath/Berliner%20Funkturm.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Berliner%20Funkturm.jpg"}'::text[], 1, '{"en": {"name": "Funkturm Berlin", "description": "Radio tower in Berlin. A lookout tower in Germany — sweeping views as a reward for stopping."}, "de": {"name": "Berliner Funkturm", "description": "146,7 Meter hoher Stahlfachwerkturm auf dem Messegelände im Berliner Ortsteil Westend. Ein Aussichtsturm in Deutschland — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Funkturm Berlin", "description": "Wieża widokowa w Niemczech — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Funkturm", "description": "Bouwwerk in Berlijn. Een uitkijktoren in Duitsland — weidse uitzichten als beloning voor de stop."}, "es": {"name": "torre de radio de Berlín", "description": "Un mirador en Alemania: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour radio de Berlin", "description": "Ancien pylône de radiodiffusion à Berlin. Une tour panoramique en Allemagne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Берлінська радіовежа", "description": "Оглядова вежа в Німеччині — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Müggelturm', 'Rozhledna a budova, Berlín - Treptow-Köpenick, Německo. Rozhledna v Německu — výhled do kraje jako odměna za zastávku.', 52.41722, 13.625, 'http://commons.wikimedia.org/wiki/Special:FilePath/Berlin%20M%C3%BCggelturm%203.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Berlin%20M%C3%BCggelturm%203.jpg"}'::text[], 2, '{"en": {"name": "Müggel-Tower", "description": "Observation tower and building, Berlin - Treptow-Köpenick, Germany. A lookout tower in Germany — sweeping views as a reward for stopping."}, "de": {"name": "Müggelturm", "description": "Aussichtsturm in Berlin. Ein Aussichtsturm in Deutschland — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Müggelturm", "description": "Wieża widokowa w Niemczech — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Müggelturm", "description": "Toren in Duitsland. Een uitkijktoren in Duitsland — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Müggelturm", "description": "Un mirador en Alemania: amplias vistas como recompensa por la parada."}, "fr": {"name": "Müggelturm", "description": "Une tour panoramique en Allemagne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Müggelturm", "description": "Оглядова вежа в Німеччині — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
