    (v_route, 'St. Leonard''s Church, Zoutleeuw', 'Rozhledna v Belgii — výhled do kraje jako odměna za zastávku.', 50.8333, 5.10304, 'http://commons.wikimedia.org/wiki/Special:FilePath/Eglise%20Saint-L%C3%A9onard%20de%20L%C3%A9au%2001.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Eglise%20Saint-L%C3%A9onard%20de%20L%C3%A9au%2001.JPG"}'::text[], 3, '{"en": {"name": "St. Leonard''s Church, Zoutleeuw", "description": "Church in Zoutleeuw, Belgium. A lookout tower in Belgium — sweeping views as a reward for stopping."}, "de": {"name": "St.-Leonardus-Kirche, Zoutleeuw", "description": "Kirchengebäude in Belgien. Ein Aussichtsturm in Belgien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "St. Leonard''s Church, Zoutleeuw", "description": "Wieża widokowa w Belgii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Sint-Leonarduskerk", "description": "Kerkgebouw in Zoutleeuw, België. Een uitkijktoren in België — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Iglesia de San Leonardo (Zoutleeuw)", "description": "Un mirador en Bélgica: amplias vistas como recompensa por la parada."}, "fr": {"name": "église Saint-Léonard de Léau", "description": "Édifice religieux belge. Une tour panoramique en Belgique — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Церква Святого Леонарда", "description": "Церква в Бельгії. Оглядова вежа у Бельгії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Basilica of Our Lady', 'Rozhledna v Belgii — výhled do kraje jako odměna za zastávku.', 50.7808, 5.4646, 'http://commons.wikimedia.org/wiki/Special:FilePath/2006.08.17.122359%20Basilika%20Tongeren%20Belgien-2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2006.08.17.122359%20Basilika%20Tongeren%20Belgien-2.jpg"}'::text[], 4, '{"en": {"name": "Basilica of Our Lady", "description": "Church in Tongeren, Belgium. A lookout tower in Belgium — sweeping views as a reward for stopping."}, "de": {"name": "Liebfrauenbasilika (Tongeren)", "description": "Belgische Kirche. Ein Aussichtsturm in Belgien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Basilica of Our Lady", "description": "Wieża widokowa w Belgii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Onze-Lieve-Vrouwebasiliek", "description": "Kerkgebouw in Tongeren, België. Een uitkijktoren in België — weidse uitzichten als beloning voor de stop."}, "es": {"name": "basílica de Nuestra Señora", "description": "Un mirador en Bélgica: amplias vistas como recompensa por la parada."}, "fr": {"name": "basilique Notre-Dame de Tongres", "description": "Édifice religieux belge. Une tour panoramique en Belgique — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Базиліка Тонгеренської Богоматері", "description": "Оглядова вежа у Бельгії — широкі краєвиди як нагорода за зупинку."}}'::jsonb);
