    (v_route, 'Schönbrunn', 'Zámek ve Vídni. Hrad či zámek v Rakousku — historická zastávka, která stojí za odbočku.', 48.18479, 16.31227, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Sch%C3%B6nbrunn%20Wien%202014%20%28Zuschnitt%202%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Sch%C3%B6nbrunn%20Wien%202014%20%28Zuschnitt%202%29.jpg"}'::text[], 0, '{"en": {"name": "Schönbrunn Palace", "description": "Palace in Vienna, Austria. A castle in Austria — a historic stop worth the detour."}, "de": {"name": "Schloss Schönbrunn", "description": "Schloss in Wien, Österreich. Eine Burg bzw. ein Schloss in Österreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Schönbrunn", "description": "Zamek w Austrii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Schloss Schönbrunn", "description": "Kasteel in Hietzing, Oostenrijk. Een kasteel in Oostenrijk — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Schönbrunn", "description": "Máxima residencia de los Habsburgo, ubicado en Viena, Austria. Un castillo en Austria: una parada histórica que merece el desvío."}, "fr": {"name": "château de Schönbrunn", "description": "Château à Vienne, Autriche. Un château en Autriche — une halte historique qui vaut le détour."}, "uk": {"name": "Шенбрунн", "description": "Палацовий комплекс у Відні, Астрія. Замок у Австрії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Hofburg', 'Palác ve Vídni. Hrad či zámek v Rakousku — historická zastávka, která stojí za odbočku.', 48.20639, 16.36528, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wien%20-%20Neue%20Hofburg.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Wien%20-%20Neue%20Hofburg.JPG"}'::text[], 1, '{"en": {"name": "Hofburg Palace", "description": "Palace located in Vienna, Austria. A castle in Austria — a historic stop worth the detour."}, "de": {"name": "Hofburg", "description": "Frühere Residenz der Habsburger und Amtssitz des Bundespräsidenten in Wien, Österreich. Eine Burg bzw. ein Schloss in Österreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Hofburg", "description": "Pałac w Wiedniu w Austrii. Zamek w Austrii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Hofburg", "description": "Paleis in Wenen. Een kasteel in Oostenrijk — een historische stop die de omweg waard is."}, "es": {"name": "Palacio Imperial de Hofburg", "description": "Residencia Oficial en Viena. Un castillo en Austria: una parada histórica que merece el desvío."}, "fr": {"name": "Hofburg", "description": "Palais, musée et résidence officielle du président fédéral autrichien. Un château en Autriche — une halte historique qui vaut le détour."}, "uk": {"name": "Гофбурґ", "description": "Замок у Австрії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála svatého Štěpána ve Vídni', 'Katedrála ve Vídni. Památka v Rakousku — kus historie přímo u trasy.', 48.20843, 16.37326, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wien%20-%20Stephansdom%20%281%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Wien%20-%20Stephansdom%20%281%29.JPG"}'::text[], 2, '{"en": {"name": "St. Stephen''s Cathedral", "description": "Church in Vienna, Austria. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Stephansdom", "description": "Kathedrale des Erzbistums Wien. Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Szczepana w Wiedniu", "description": "Świątynia katolicka. Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Stephansdom", "description": "Rooms-katholieke kathedraal in Wenen, Oostenrijk. Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Esteban", "description": "Catedral católica de Viena. Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Étienne de Vienne", "description": "Cathédrale de Vienne. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святого Стефана", "description": "Каферальний собор у Відні, Австрія. Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Stadttempel', 'Synagoga ve Vídni. Památka v Rakousku — kus historie přímo u trasy.', 48.21165, 16.37483, 'http://commons.wikimedia.org/wiki/Special:FilePath/Stadttempel%20Vienna%20September%202006%20010.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Stadttempel%20Vienna%20September%202006%20010.jpg"}'::text[], 3, '{"en": {"name": "Stadttempel", "description": "Synagogue in Vienna, Austria. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Stadttempel", "description": "Synagoge in der Wiener Inneren Stadt (40865). Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Stadttempel", "description": "Synagoga (Wiedeń, Austria). Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Stadttempel", "description": "Synagoge in Wenen, Oostenrijk. Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Stadttempel", "description": "Sinagoga de Viena. Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "Stadttempel", "description": "Synagogue à Vienne. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "Штадттемпель", "description": "Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Liechtenstein', 'Hrad v Rakousku. Hrad či zámek v Rakousku — historická zastávka, která stojí za odbočku.', 48.0927, 16.27036, 'http://commons.wikimedia.org/wiki/Special:FilePath/Maria%20Enzersdorf%20-%20Burg%20Liechtenstein%20%281%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Maria%20Enzersdorf%20-%20Burg%20Liechtenstein%20%281%29.JPG"}'::text[], 4, '{"en": {"name": "Liechtenstein Castle", "description": "Castle located near Maria Enzersdorf in Lower Austria bordering Vienna. A castle in Austria — a historic stop worth the detour."}, "de": {"name": "Burg Liechtenstein", "description": "Burg in Österreich. Eine Burg bzw. ein Schloss in Österreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Liechtenstein", "description": "Zamek w miejscowości Maria Enzersdorf w Austrii. Zamek w Austrii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel Liechtenstein", "description": "Kasteel in Oostenrijk. Een kasteel in Oostenrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Liechtenstein", "description": "Castillo situado cerca de Maria Enzersdorf en Baja Austria, cerca de Viena. Un castillo en Austria: una parada histórica que merece el desvío."}, "fr": {"name": "château de Liechtenstein", "description": "Château autrichien. Un château en Autriche — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Ліхтенштейн", "description": "Замок у Австрії — історична зупинка, варта об''їзду."}}'::jsonb),
