    (v_route, 'Terezín', 'Město v okrese Litoměřice v Ústeckém kraji. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 50.51108, 14.15064, 'http://commons.wikimedia.org/wiki/Special:FilePath/Terez%C3%ADn%20-%20n%C3%A1m%C4%9Bst%C3%AD%20%C4%8CSA%2C%20pohled%20od%20SZ%2C%20obr01.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Terez%C3%ADn%20-%20n%C3%A1m%C4%9Bst%C3%AD%20%C4%8CSA%2C%20pohled%20od%20SZ%2C%20obr01.jpg"}'::text[], 0, '{"en": {"name": "Terezín", "description": "Municipality in Czechia. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Terezín", "description": "Gemeinde in Tschechien, Festung 1780-1882. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Terezin", "description": "Miasto w Czechach. Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Theresienstadt", "description": "Stad in Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Terezín", "description": "Municipio de la República Checa. Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Terezín", "description": "Commune tchèque. Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Терезін", "description": "Місто в Чехії. Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
