    (v_route, 'Bratislavský hrad', 'Hrad na Slovensku. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 48.14222, 17.1, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bratislava%20-%20Burg%20%28a%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bratislava%20-%20Burg%20%28a%29.JPG"}'::text[], 0, '{"en": {"name": "Bratislava Castle", "description": "Castle in Europe. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Bratislavaer Burg", "description": "Burg in der Slowakei. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Bratysławski", "description": "Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel van Bratislava", "description": "Kasteel in Slowakije. Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Bratislava", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Bratislava", "description": "Château slovaque. Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Братиславський Град", "description": "Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
