    (v_route, 'most Slovenského národního povstání', 'Most přes Dunaj v Bratislavě. Rozhledna v Slovensku — výhled do kraje jako odměna za zastávku.', 48.13833, 17.10444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bratislava%20New%20Bridge%20from%20castle%20hill.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bratislava%20New%20Bridge%20from%20castle%20hill.JPG"}'::text[], 3, '{"en": {"name": "Bridge of the Slovak National Uprising", "description": "Bridge over Danube in Bratislava, Slovakia. A lookout tower in Slovakia — sweeping views as a reward for stopping."}, "de": {"name": "Brücke des Slowakischen Nationalaufstandes", "description": "Brücke über die Donau in Bratislava. Ein Aussichtsturm in der Slowakei — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Most SNP", "description": "Most nad Dunajem. Wieża widokowa w Słowacji — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Nový Most", "description": "Brug voor wegverkeer over de Donau in Bratislava. Een uitkijktoren in Slowakije — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Most SNP", "description": "Un mirador en Eslovaquia: amplias vistas como recompensa por la parada."}, "fr": {"name": "pont du Soulèvement national slovaque", "description": "Pont de Bratislava. Une tour panoramique en Slovaquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Міст СНП", "description": "Міст у Братиславі. Оглядова вежа в Словаччині — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Televizní věž na Kamzíku', 'Rozhledna v Slovensku — výhled do kraje jako odměna za zastávku.', 48.1825, 17.09444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bratislava%20-%20Fernsehturm%20%28a%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bratislava%20-%20Fernsehturm%20%28a%29.JPG"}'::text[], 4, '{"en": {"name": "Kamzík TV Tower", "description": "Observation tower. A lookout tower in Slovakia — sweeping views as a reward for stopping."}, "de": {"name": "Fernsehturm Bratislava", "description": "Ein Aussichtsturm in der Slowakei — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża telewizyjna Kamzík", "description": "Wieża widokowa w Słowacji — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Televizní věž na Kamzíku", "description": "Uitkijktoren in Slowakije. Een uitkijktoren in Slowakije — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre de TV de Kamzík", "description": "Un mirador en Eslovaquia: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour de télévision du Kamzík", "description": "Une tour panoramique en Slovaquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Televizní věž na Kamzíku", "description": "Оглядова вежа в Словаччині — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
