    (v_route, 'Śniardwy', 'Největší jezero v Polsku. Vodní plocha v Polsku — příjemný cíl vyjížďky s výhledy na hladinu.', 53.75, 21.71667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Jezioro%20%C5%9Aniardwy%2C%20widok%20z%20Nied%C5%BAwiedziego%20Rogu%20%282017%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Jezioro%20%C5%9Aniardwy%2C%20widok%20z%20Nied%C5%BAwiedziego%20Rogu%20%282017%29.jpg"}'::text[], 0, '{"en": {"name": "Śniardwy", "description": "Lake in Poland. A body of water in Poland — a pleasant ride destination with waterside views."}, "de": {"name": "Śniardwy", "description": "See in Polen, Spirdingsee. Ein Gewässer in Polen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Śniardwy", "description": "Jezioro w Polsce. Akwen w Polsce — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Śniardwymeer", "description": "Meer in Polen. Een waterpartij in Polen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Śniardwy", "description": "Lago en Polonia. Una masa de agua en Polonia: un destino agradable con vistas al agua."}, "fr": {"name": "Śniardwy", "description": "Lac en Pologne. Un plan d''eau en Pologne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Снярдви", "description": "Озеро Польщі. Водойма в Польщі — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
