    (v_route, 'Katedrála na Wawelu', 'Katedrála v Krakově. Památka v Polsku — kus historie přímo u trasy.', 50.05464, 19.93542, 'http://commons.wikimedia.org/wiki/Special:FilePath/292%20Krakow%20Katedra%20na%20Wawelu%2020070805.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/292%20Krakow%20Katedra%20na%20Wawelu%2020070805.jpg"}'::text[], 0, '{"en": {"name": "Wawel Cathedral", "description": "Cathedral in Kraków, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Wawel-Kathedrale", "description": "Kirchengebäude im Wawel-Schloss in Krakau. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Archikatedralna św. Stanisława i św. Wacława w Krakowie", "description": "Świątynia katolicka w Polsce. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Wawelkathedraal", "description": "Kathedraal in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Wawel", "description": "Templo católico de Cracovia (Polonia). Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale du Wawel", "description": "Édifice religieux situé en Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святих Станіслава і Вацлава", "description": "Кафедральний собор у Кракові, Польща. Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Kostel Nanebevzetí Panny Marie v Krakově', 'Kostel v Krakově v Polsku. Památka v Polsku — kus historie přímo u trasy.', 50.06167, 19.93917, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kosciol%20mariacki%20krakow.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kosciol%20mariacki%20krakow.jpg"}'::text[], 1, '{"en": {"name": "St. Mary''s Basilica in Kraków", "description": "Church (Kraków, Poland). A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Marienkirche", "description": "Kirchengebäude in Krakau, Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "kościół archiprezbiterialny pw. Wniebowzięcia Najświętszej Marii Panny w Krakowie", "description": "Zabytkowy kościół w Krakowie. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Mariakerk", "description": "Krakau. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de Santa María", "description": "Iglesia de Santa María en Cracovia, Polonia. Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Sainte-Marie de Cracovie", "description": "Édifice religieux situé à Cracovie en Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Архипресвітеріальний костел Внебовзяття Пресвятої Діви Марії", "description": "Костел у Кракові. Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Floriánská brána', 'Brána v Krakově. Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 50.06472, 19.94139, 'http://commons.wikimedia.org/wiki/Special:FilePath/20200516%20Brama%20Floria%C5%84ska%20w%20Krakowie%200911%209966.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/20200516%20Brama%20Floria%C5%84ska%20w%20Krakowie%200911%209966.jpg"}'::text[], 2, '{"en": {"name": "St. Florian''s Gate", "description": "Gothic tower in Kraków, Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Florianstor", "description": "Das letzte erhaltene Stadttor von Krakau im Zug der Floriansgasse. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Brama Floriańska w Krakowie", "description": "Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Florianuspoort", "description": "Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Puerta de San Florián", "description": "Puerta de la ciudad Cracovia unica preservada. Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "porte Florian", "description": "Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Брама Флоріанська (Краків)", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Kostel svatého Floriána', 'Kostel v Krakově. Památka v Polsku — kus historie přímo u trasy.', 50.06756, 19.94333, 'http://commons.wikimedia.org/wiki/Special:FilePath/20180114%20Ko%C5%9Bci%C3%B3%C5%82%20%C5%9Bw.%20Floriana%20w%20Krakowie%200108%20DxO.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/20180114%20Ko%C5%9Bci%C3%B3%C5%82%20%C5%9Bw.%20Floriana%20w%20Krakowie%200108%20DxO.jpg"}'::text[], 3, '{"en": {"name": "St. Florian''s Church", "description": "Church building in Kraków, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Floriansbasilika", "description": "Kirchengebäude in Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół św. Floriana w Krakowie", "description": "Bazylika w Krakowie. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Floriaankerk", "description": "Krakau. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "iglesia de San Florián", "description": "Cracovia. Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Florian", "description": "Église romane et baroque de Cracovie en Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Костел святого Флоріана", "description": "Костел у Кракові. Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Stará synagoga v Krakově', 'Památka v Polsku — kus historie přímo u trasy.', 50.05139, 19.94857, 'http://commons.wikimedia.org/wiki/Special:FilePath/Alte%20Synagoge%20%28Krakau%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Alte%20Synagoge%20%28Krakau%29.jpg"}'::text[], 4, '{"en": {"name": "Old Synagogue in Kraków", "description": "Former synagogue in Kazimierz, now Judaic Museum in Kraków. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Alte Synagoge", "description": "Gebäude in Krakau, Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga Stara w Krakowie", "description": "Była synagoga na Kazimierzu, obecnie oddział Muzeum Historycznego Miasta Krakowa - Muzeum Judaistyczne. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Oude Synagoge", "description": "Gebouw in Krakow, Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Stará synagoga v Krakově", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "ancienne synagogue", "description": "Bâtiment de Cracovie. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Стара Синагога (Краків)", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
