    (v_route, 'Kampinos Forest', 'Prales rozkládající se v povodí Visly v Mazovském vojvodství nyní na rozloze 240 km2. Vqětšinu jeho území chrání Kampinoský národní park. Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 52.32361, 20.59833, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dziekanow%20KPN.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dziekanow%20KPN.jpg"}'::text[], 7, '{"en": {"name": "Kampinos Forest", "description": "Forest in central Poland. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "Kampinos Urwald", "description": "Urwald und Naturschutzgebiet in Polen. Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Puszcza Kampinoska", "description": "Kompleks leśny leżący w centralnej Polsce. Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Kampinos Forest", "description": "Bos in Polen. Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "Bosque de Kampinos", "description": "Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "forêt de Kampinos", "description": "Forêt polonaise. Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Кампіноська пуща", "description": "Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb);
