    (v_route, 'Katedrála svatého Ruperta a Virgila', 'Katedrála v Salcburku. Památka v Rakousku — kus historie přímo u trasy.', 47.79778, 13.04694, 'http://commons.wikimedia.org/wiki/Special:FilePath/Salzburg%20cathedral%20frontview01.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Salzburg%20cathedral%20frontview01.jpg"}'::text[], 0, '{"en": {"name": "Salzburg Cathedral", "description": "Church in Austria. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Salzburger Dom", "description": "Kirchengebäude in Salzburg. Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Ruperta w Salzburgu", "description": "Świątynia katolicka. Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Salzburg", "description": "Bouwwerk in Salzburg. Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Salzburgo", "description": "Catedral católica de Salzburgo, Austria. Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Rupert de Salzbourg", "description": "Cathédrale en Autriche. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "Зальцбурзький собор", "description": "Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb),
