    (v_route, 'Slovinský národní park', 'Národní park, Pomořské vojvodství, Polsko. Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 54.7032, 17.3069, 'http://commons.wikimedia.org/wiki/Special:FilePath/S%C5%82owi%C5%84ski%20Park%20Narodowy%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/S%C5%82owi%C5%84ski%20Park%20Narodowy%201.jpg"}'::text[], 0, '{"en": {"name": "Słowiński National Park", "description": "National park of Poland. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "Slowinzischer Nationalpark", "description": "Nationalpark in Polen. Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Słowiński Park Narodowy", "description": "Park narodowy w Polsce. Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal park Słowiński", "description": "Natuurgebied in Polen. Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Słowiński", "description": "Área protegida de Polonia. Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Słowiński", "description": "Parc national de Pologne. Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Словінський національний парк", "description": "Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Łebsko', 'Pobřežní jezero v Polsku. Vodní plocha v Polsku — příjemný cíl vyjížďky s výhledy na hladinu.', 54.71361, 17.40889, 'http://commons.wikimedia.org/wiki/Special:FilePath/SlowinNP-Lebsko2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/SlowinNP-Lebsko2.jpg"}'::text[], 1, '{"en": {"name": "Łebsko Lake", "description": "Lake in Żarnowska, Pomeranian Voivodeship, Poland. A body of water in Poland — a pleasant ride destination with waterside views."}, "de": {"name": "Łebsko", "description": "See in Polen. Ein Gewässer in Polen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Łebsko", "description": "Jezioro na Wybrzeżu Słowińskim. Akwen w Polsce — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Łebsko", "description": "Meer in Polen. Een waterpartij in Polen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Łebsko", "description": "Una masa de agua en Polonia: un destino agradable con vistas al agua."}, "fr": {"name": "Łebsko", "description": "Lac en Pologne. Un plan d''eau en Pologne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Лебсько", "description": "Водойма в Польщі — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
