    (v_route, 'zámek Kroměříž', 'Zámek v České republice. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.30028, 17.39306, 'http://commons.wikimedia.org/wiki/Special:FilePath/Krom%C4%9B%C5%99%C3%AD%C5%BE%20z%C3%A1mek%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Krom%C4%9B%C5%99%C3%AD%C5%BE%20z%C3%A1mek%201.jpg"}'::text[], 0, '{"en": {"name": "Kroměříž Castle", "description": "Castle in the Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Schloss ​Kremsier", "description": "Schloss in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Arcybiskupi w Kromieryżu", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Aartsbisschoppelijk paleis te Kroměříž", "description": "Paleis in Kroměříž, Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Palacio arzobispal de Kroměříž", "description": "Castillo-palacio en Chequia. Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Kroměříž", "description": "Château en République tchèque. Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Кромержиж", "description": "Замок у Чехії. Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
