    (v_route, 'Jasná Hora', 'Klášter. Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 50.8125, 19.09722, 'http://commons.wikimedia.org/wiki/Special:FilePath/Jasna%20G%C3%B3ra%20i%20otoczenie%2006.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Jasna%20G%C3%B3ra%20i%20otoczenie%2006.jpg"}'::text[], 0, '{"en": {"name": "Jasna Góra Monastery", "description": "Historic Catholic shrine and pilgrimage site in Częstochowa, Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Jasná Hora", "description": "Kloster in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Jasná Hora", "description": "Sanktuarium, zespół klasztorny zakonu paulinów w Częstochowie. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Jasná Hora", "description": "Klooster in Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Jasná Hora", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "Jasná Hora", "description": "Sanctuaire polonais. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Ясна Ґура", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
