    (v_route, 'Ambras', 'Hrad či zámek v Rakousku — historická zastávka, která stojí za odbočku.', 47.25667, 11.43472, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Ambras%20Park%20und%20Garten%2010.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Ambras%20Park%20und%20Garten%2010.jpg"}'::text[], 0, '{"en": {"name": "Ambras Castle", "description": "Castle in Innsbruck, Austria. A castle in Austria — a historic stop worth the detour."}, "de": {"name": "Schloss Ambras", "description": "Schloss in Innsbruck, Österreich. Eine Burg bzw. ein Schloss in Österreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Ambras", "description": "Zamek w Austrii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Schloss Ambras", "description": "Casteel in Innsbruck, Oostenrijk. Een kasteel in Oostenrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Ambras", "description": "Palacio en Innbrusck (Austria). Un castillo en Austria: una parada histórica que merece el desvío."}, "fr": {"name": "château d''Ambras", "description": "Château à Innsbruck, Autriche. Un château en Autriche — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Амбрас", "description": "Замок в Інсбруку, Австрія. Замок у Австрії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Hofburg v Innsbrucku', 'Sídlo tyrolských knížat. Hrad či zámek v Rakousku — historická zastávka, která stojí za odbočku.', 47.2689, 11.3944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Insbruk%20Hofburg%20%C4%8Delo%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Insbruk%20Hofburg%20%C4%8Delo%201.jpg"}'::text[], 1, '{"en": {"name": "Hofburg, Innsbruck", "description": "Habsburg palace in Innsbruck, Austria, and considered one of the three most significant cultural buildings in the country, along with the Hofburg Palace and Schönbrunn Palace in Vienna. A castle in Austria — a historic stop worth the detour."}, "de": {"name": "Hofburg", "description": "Schloss in Innsbruck, Österreich. Eine Burg bzw. ein Schloss in Österreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Hofburg", "description": "Pałac w Innsbrucku. Zamek w Austrii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Hofburg", "description": "Paleis in Innsbruck, Oostenrijk. Een kasteel in Oostenrijk — een historische stop die de omweg waard is."}, "es": {"name": "Hofburg", "description": "Un castillo en Austria: una parada histórica que merece el desvío."}, "fr": {"name": "Hofburg", "description": "Château autrichien. Un château en Autriche — une halte historique qui vaut le détour."}, "uk": {"name": "Гофбург", "description": "Палац Габсбургів у Іннсбруку, Австрія. Замок у Австрії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála v Innsbrucku', 'Památka v Rakousku — kus historie přímo u trasy.', 47.26936, 11.39417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dom%20zu%20St%20Jakob%20%28IMG%202072%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dom%20zu%20St%20Jakob%20%28IMG%202072%29.jpg"}'::text[], 2, '{"en": {"name": "Innsbruck Cathedral", "description": "Church building in Innsbruck, Austria. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Dom zu St. Jakob", "description": "Kirchengebäude in Innsbruck. Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Jakuba w Innsbrucku", "description": "Świątynia katolicka. Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Innsbruck", "description": "Kathedraal in Oostenrijk. Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Santiago", "description": "Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Jacques d''Innsbruck", "description": "Église autrichienne. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святого Якова", "description": "Головний католицький храм Інсбрука в Австрії. Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Leutaschklamm', 'Vodní plocha v Rakousku — příjemný cíl vyjížďky s výhledy na hladinu.', 47.4282, 11.2464, 'http://commons.wikimedia.org/wiki/Special:FilePath/Leutaschklamm03a.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Leutaschklamm03a.jpg"}'::text[], 3, '{"en": {"name": "Leutasch Gorge", "description": "Gorge in Germany and Austria. A body of water in Austria — a pleasant ride destination with waterside views."}, "de": {"name": "Leutaschklamm", "description": "Klamm im bayerisch-tirolischen Grenzgebiet. Ein Gewässer in Österreich — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Leutaschklamm", "description": "Akwen w Austrii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Leutaschklamm", "description": "Dal in Duitsland. Een waterpartij in Oostenrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Leutaschklamm", "description": "Una masa de agua en Austria: un destino agradable con vistas al agua."}, "fr": {"name": "Leutaschklamm", "description": "Un plan d''eau en Autriche — une belle destination avec vue sur l''eau."}, "uk": {"name": "Каньйон Льойташ", "description": "Каньйон у баварсько-тирольському прикордонному районі. Водойма в Австрії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Tratzberg Castle', 'Hrad či zámek v Rakousku — historická zastávka, která stojí za odbočku.', 47.3847, 11.7431, 'http://commons.wikimedia.org/wiki/Special:FilePath/Stans%20-%20Schloss%20Tratzberg.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Stans%20-%20Schloss%20Tratzberg.JPG"}'::text[], 4, '{"en": {"name": "Tratzberg Castle", "description": "Château. A castle in Austria — a historic stop worth the detour."}, "de": {"name": "Schloss Tratzberg", "description": "Schloss in Österreich. Eine Burg bzw. ein Schloss in Österreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Tratzberg Castle", "description": "Zamek w Austrii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Tratzberg Castle", "description": "Kasteel in Oostenrijk. Een kasteel in Oostenrijk — een historische stop die de omweg waard is."}, "es": {"name": "Tratzberg Castle", "description": "Un castillo en Austria: una parada histórica que merece el desvío."}, "fr": {"name": "château de Tratzberg", "description": "Château au Tyrol, Autriche. Un château en Autriche — une halte historique qui vaut le détour."}, "uk": {"name": "Tratzberg Castle", "description": "Замок у Австрії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Spannagelhöhle', 'Přírodní zajímavost v Rakousku — místo na protažení nohou uprostřed přírody.', 47.08028, 11.67167, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kolkgang.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kolkgang.jpg"}'::text[], 5, '{"en": {"name": "Spannagel Cave", "description": "Cave. A natural sight in Austria — a spot to stretch your legs amid nature."}, "de": {"name": "Spannagelhöhle", "description": "Höhle in Tirol, Österreich. Eine Natursehenswürdigkeit in Österreich — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Spannagelhöhle", "description": "Jaskinia turystyczna (Tux, Austria). Atrakcja przyrodnicza w Austrii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Spannagelhöhle", "description": "Een natuurbezienswaardigheid in Oostenrijk — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cueva de Spannagel", "description": "Un paraje natural en Austria: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Spannagelhöhle", "description": "Un site naturel en Autriche — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Шпаннагель", "description": "Природна пам''ятка в Австрії — місце розім''яти ноги серед природи."}}'::jsonb),
