    (v_route, 'Kurtkowiec', 'Ledovcové jezero v Polsku. Vodní plocha v Polsku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.2294, 20.0039, 'http://commons.wikimedia.org/wiki/Special:FilePath/20161001%20Kurtkowiec%20i%20Czerwone%20Stawy%20G%C4%85sienicowe%201730.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/20161001%20Kurtkowiec%20i%20Czerwone%20Stawy%20G%C4%85sienicowe%201730.jpg"}'::text[], 2, '{"en": {"name": "Kurtkowiec", "description": "Lake in Poland. A body of water in Poland — a pleasant ride destination with waterside views."}, "de": {"name": "Kurtkowiec", "description": "Ein Gewässer in Polen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Kurtkowiec", "description": "Akwen w Polsce — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Kurtkowiec", "description": "Meer in Polen. Een waterpartij in Polen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Kurtkowiec", "description": "Una masa de agua en Polonia: un destino agradable con vistas al agua."}, "fr": {"name": "Kurtkowiec", "description": "Lac en Pologne. Un plan d''eau en Pologne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Kurtkowiec", "description": "Озеро в Польщі. Водойма в Польщі — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
