    (v_route, 'Národní park Nízké Tatry', 'Národní park na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.92556, 19.6325, 'http://commons.wikimedia.org/wiki/Special:FilePath/Low%20tatra%20dumbier.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Low%20tatra%20dumbier.jpg"}'::text[], 0, '{"en": {"name": "Low Tatras National Park", "description": "National park in Central Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Niedere Tatra", "description": "Nationalpark in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Niżne Tatry", "description": "Słowacki park narodowy. Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Lage Tatra", "description": "Natuurgebied in Slowakije. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de la Baja Tatra", "description": "Espacio Natural. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national des Basses Tatras", "description": "Parc national de Slovaquie. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Низькі Татри (національний парк)", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Vrbické pleso', 'Národní přírodní památka. Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 48.97, 19.57722, 'http://commons.wikimedia.org/wiki/Special:FilePath/N%C3%ADzke%20Tatry%20Vrbick%C3%A9%20pleso%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/N%C3%ADzke%20Tatry%20Vrbick%C3%A9%20pleso%2001.jpg"}'::text[], 1, '{"en": {"name": "Vrbické pleso", "description": "Lake in Liptovský Mikuláš District, Slovakia. A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Vrbické pleso", "description": "Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Vrbické pleso", "description": "Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Vrbické pleso", "description": "Meer in Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Vrbicke pleso", "description": "Área protegida de Eslovaquia. Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Vrbické pleso", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Vrbické pleso", "description": "Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
