    (v_route, 'Kampinoský národní park', 'Národní park v Mazovském vojvodství na území Kampinoského pralesa. Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 52.31667, 20.56667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Poland%20Kampinos%20Alces%20alces%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Poland%20Kampinos%20Alces%20alces%201.jpg"}'::text[], 0, '{"en": {"name": "Kampinos National Park", "description": "National park of Poland. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Kampinos", "description": "Nationalpark in Polen. Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Kampinoski Park Narodowy", "description": "Polski park narodowy utworzony w 1959 roku. Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Kampinos National Park", "description": "Nationaal park in Polen. Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Kampinos", "description": "Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Kampinos", "description": "Parc national de Pologne. Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Кампіноський національний парк", "description": "Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb),
