    (v_route, 'Štětínský zámek', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 53.42621, 14.56036, 'http://commons.wikimedia.org/wiki/Special:FilePath/Szczecin%20Zamek%20Ksiazat%20Pomorskich%20%28od%20pln-zach%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Szczecin%20Zamek%20Ksiazat%20Pomorskich%20%28od%20pln-zach%29.jpg"}'::text[], 1, '{"en": {"name": "Ducal Castle", "description": "Castle in Szczecin, Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Stettiner Schloss", "description": "Schloss in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Książąt Pomorskich w Szczecinie", "description": "Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Slot van Stettin", "description": "Kasteel in Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Ducal de Szczecin", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "château ducal de Szczecin", "description": "Château polonais. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Щецинський замок", "description": "Замок (споруда). Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
