    (v_route, 'Katedrála svatého Jakuba ve Štětíně', 'Katedrála v Polsku. Památka v Polsku — kus historie přímo u trasy.', 53.42472, 14.55528, 'http://commons.wikimedia.org/wiki/Special:FilePath/Szczecin%20katedra%20sw%20Jakuba%20%282%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Szczecin%20katedra%20sw%20Jakuba%20%282%29.jpg"}'::text[], 3, '{"en": {"name": "Cathedral Basilica of St. James the Apostle", "description": "Cathedral in Szczecin, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Jakobskathedrale", "description": "Kirchengebäude in Stettin. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Archikatedralna św. Jakuba Apostoła w Szczecinie", "description": "Świątynia katolicka, główny kościół archidiecezji szczecińsko-kamieńskiej. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Jacobuskathedraal", "description": "Kathedraal in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Santiago Apóstol", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Jacques de Szczecin", "description": "Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Jakuba ve Štětíně", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
